        let queued_shown = self.tasks_tab.queued_expanded;
        if queued_shown && self.queue.is_empty() {
            rows.push(TimelineRow::Empty("tasks-queued-empty", "No queued prompts"));
        }
        let first_queued = rows.len();
        if queued_shown {
            rows.extend((0..self.queue.len()).map(|_| TimelineRow::Queued));
            // A chain waiting on a step in the queue, listed with it.
            for (head, members) in
                self.chains_where(|this, members| this.chain_state(members) == ChainState::Queued)
            {
                rows.push(TimelineRow::Chain(head, members));
            }
        }
        (rows, running_at, queued_at, first_queued)
    }
